1	import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
2	import prisma from "../lib/prisma.js";
3	import jwt from "jsonwebtoken";
4	
5	const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
6	
7	// Authorization 헤더에서 토큰 추출
8	function extractToken(request: FastifyRequest): string | null {
9	  const auth = request.headers.authorization;
10	  if (!auth) return null;
11	  const match = auth.match(/^Token\s+(.+)$/i);
12	  return match ? match[1] : null;
13	}
14	
15	// 토큰 디코딩 (예외 처리 포함)
16	function verifyToken(token: string): { id: string; username: string; email: string } | null {
17	  try {
18	    return jwt.verify(token, JWT_SECRET) as any;
19	  } catch {
20	    return null;
21	  }
22	}
23	
24	// 슬러그 생성: 소문자, 공백→하이픈, 특수문자 제거, 중복 슬러그 처리
25	function slugify(title: string, existingSlugs: string[] = []): string {
26	  let slug = title
27	    .toLowerCase()
28	    .trim()
29	    .replace(/[^\w\s-]/g, "")
30	    .replace(/[\s_]+/g, "-")
31	    .replace(/^-+|-+$/g, "");
32	  let suffix = 1;
33	  while (existingSlugs.includes(slug)) {
34	    slug = `${slug}-${suffix++}`;
35	  }
36	  return slug;
37	}
38	
39	// 태그 정규화: 소문자, 공백 제거, 빈 값 필터링
40	function normalizeTags(tagList: (string | null | undefined)[]): string[] {
41	  if (!tagList) return [];
42	  const tags = tagList
43	    .map((t) => {
44	      if (t === null || t === undefined || t === "") return null;
45	      return t.trim().toLowerCase();
46	    })
47	    .filter((t): t is string => t !== null && t !== "");
48	  return [...new Set(tags)];
49	}
50	
51	// 아티클 응답 포맷팅 헬퍼 (태그, 즐겨찾기, 저자 정보 포함)
52	function formatArticleResponse(
53	  article: any,
54	  tagNames: string[],
55	  favorited: boolean,
56	  favoritesCount: number,
57	  currentUserId: string | null,
58	): any {
59	  let following = false;
60	  if (currentUserId && currentUserId !== article.authorId) {
61	    following = false;
62	  }
63	  return {
64	    title: article.title,
65	    slug: article.slug,
66	    description: article.description,
67	    body: article.body,
68	    tagList: tagNames,
69	    createdAt: article.createdAt,
70	    updatedAt: article.updatedAt,
71	    favorited,
72	    favoritesCount,
73	    author: {
74	      username: article.author.username,
75	      bio: article.author.bio ?? null,
76	      image: article.author.image ?? null,
77	      following,
78	    },
79	  };
80	}
81	
82	export async function articlesRoutes(app: FastifyInstance): Promise<void> {
83	  // POST /api/articles - 아티클 생성
84	  app.post("/api/articles", async (request, reply) => {
85	    const token = extractToken(request);
86	    if (!token) {
87	      return reply.code(401).send({ errors: { token: ["is missing"] } });
88	    }
89	
90	    const { article } = (request.body as any) as { article?: any };
91	    const { title, description, body, tagList } = article || {};
92	
93	    // 필수 필드 검증
94	    if (!title || title.trim() === "") {
95	      return reply.code(422).send({ errors: { title: ["can't be blank"] } });
96	    }
97	    if (!description || description.trim() === "") {
98	      return reply.code(422).send({ errors: { description: ["can't be blank"] } });
99	    }
100	    if (!body || body.trim() === "") {
101	      return reply.code(422).send({ errors: { body: ["can't be blank"] } });
102	    }
103	
104	    const decoded = verifyToken(token);
105	    if (!decoded) {
106	      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
107	    }
108	    const normalizedTags = normalizeTags(tagList);
109	
110	    // 태그 조회/생성
111	    let tagRecords: { id: string; name: string }[] = [];
112	    if (normalizedTags.length > 0) {
113	      const existingTags = await prisma.tag.findMany({
114	        where: { name: { in: normalizedTags } },
115	        select: { id: true, name: true },
116	      });
117	      const existingNames = new Set(existingTags.map((t) => t.name));
118	      const newTags = normalizedTags.filter((n) => !existingNames.has(n));
119	
120	      if (newTags.length > 0) {
121	        await prisma.tag.createMany({
122	          data: newTags.map((name) => ({ name })),
123	        });
124	      }
125	      tagRecords = await prisma.tag.findMany({
126	        where: { name: { in: normalizedTags } },
127	        select: { id: true, name: true },
128	      });
129	    }
130	
131	    // 기존 슬러그 목록 조회 후 중복 처리
132	    const existingSlugs = await prisma.article.findMany({
133	      select: { slug: true },
134	    });
135	    const existingSlugList = existingSlugs.map((a) => a.slug);
136	    const slug = slugify(title, existingSlugList);
137	    const created = await prisma.article.create({
138	      data: {
139	        title: title.trim(),
140	        description: description.trim(),
141	        body: body.trim(),
142	        slug,
143	        authorId: decoded.id,
144	        ...(tagRecords.length > 0
145	          ? { tagList: { connect: tagRecords.map((t) => ({ id: t.id })) } }
146	          : {}),
147	      },
148	      include: {
149	        author: {
150	          select: { id: true, username: true, bio: true, image: true },
151	        },
152	        tagList: { select: { name: true } },
153	      },
154	    });
155	
156	    // 아티클 생성 후 태그 이름 추출
157	    const tagNames = (created.tagList as Array<{ name: string }> || []).map(
158	      (t) => t.name,
159	    );
160	
161	    // favorited 상태 기본값
162	    let favorited = false;
163	    let favoritesCount = 0;
164	
165	    return reply.code(201).send({
166	      article: formatArticleResponse(created, tagNames, favorited, favoritesCount, null),
167	    });
168	  });
169	
170	  // GET /api/articles - 아티클 목록 조회 (필터: author, tag, favorited)
171	  app.get("/api/articles", async (request: any, reply) => {
172	    const token = extractToken(request);
173	    const authorFilter = request.query?.author as string | undefined;
174	    const tagFilter = request.query?.tag as string | undefined;
175	    const favoritedFilter = request.query?.favorited as string | undefined;
176	    const limit = Math.min(parseInt(request.query?.limit as string ?? "20", 10), 100);
177	    const offset = parseInt(request.query?.offset as string ?? "0", 10);
178	
179	    // 현재 사용자 ID 추출
180	    let currentUserId: string | null = null;
181	    if (token) {
182	      try {
183	        currentUserId = verifyToken(token)?.id ?? null;
184	      } catch {
185	        /* invalid token */
186	      }
187	    }
188	
189	    // favorited 필터 — 먼저 존재하여 articleIds 확보
190	    let favArticleIds: string[] = [];
191	    if (favoritedFilter) {
192	      const favUser = await prisma.user.findUnique({ where: { username: favoritedFilter } });
193	      if (!favUser) {
194	        return reply.send({ articles: [], articlesCount: 0 });
195	      }
196	      const favResults = await prisma.favorite.findMany({
197	        where: { userId: favUser.id },
198	        select: { articleId: true },
199	      });
200	      favArticleIds = favResults.map((f) => f.articleId);
201	    }
202	
203	    // author 필터
204	    let authorId: string | undefined;
205	    if (authorFilter) {
206	      const author = await prisma.user.findUnique({ where: { username: authorFilter } });
207	      if (!author) {
208	        return reply.send({ articles: [], articlesCount: 0 });
209	      }
210	      authorId = author.id;
211	    }
212	
213	    // tag 필터
214	    let tagId: string | undefined;
215	    if (tagFilter) {
216	      const tag = await prisma.tag.findUnique({ where: { name: tagFilter } });
217	      if (!tag) {
218	        return reply.send({ articles: [], articlesCount: 0 });
219	      }
220	      tagId = tag.id;
221	    }
222	
223	    // where 조건 구성
224	    const where: any = {};
225	    if (authorId) where.authorId = authorId;
226	    if (favArticleIds.length > 0) {
227	      where.id = { in: favArticleIds };
228	    }
229	    if (tagId) {
230	      where.tags = { some: { id: tagId } };
231	    }
232	
233	    // 전체 카운트
234	    const total = await prisma.article.count({ where });
235	
236	    const articles = await prisma.article.findMany({
237	      where,
238	      include: {
239	        author: {
240	          select: { id: true, username: true, bio: true, image: true },
241	        },
242	        tagList: { select: { name: true } },
243	      },
244	      orderBy: { createdAt: "desc" },
245	      take: limit,
246	      skip: offset,
247	    });
248	
249	    // favorited 상태 batch 체크
250	    const articleIds = articles.map((a: any) => a.id);
251	    let favoritedMap: Record<string, boolean> = {};
252	    let favCountMap: Record<string, number> = {};
253	
254	    if (articleIds.length > 0) {
255	      for (const aid of articleIds) {
256	        const favs = await prisma.favorite.findMany({
257	          where: { articleId: aid },
258	          select: { userId: true },
259	        });
260	        favCountMap[aid] = favs.length;
261	        if (favs.some((f) => f.userId === currentUserId)) {
262	          favoritedMap[aid] = true;
263	        }
264	      }
265	    }
266	
267	    // 팔로우 관계 batch 조회
268	    let followingMap: Record<string, boolean> = {};
269	    if (articles.length > 0 && currentUserId) {
270	      const followedAuthorIds = articles
271	        .map((a: any) => a.author.id)
272	        .filter((id: string) => id);
273	      if (followedAuthorIds.length > 0) {
274	        const followResults = await prisma.$queryRaw<{ following_id: string }[]>`
275	          SELECT following_id FROM "Follow" WHERE follower_id = ${currentUserId} AND following_id IN (${followedAuthorIds})
276	        `;
277	        for (const row of followResults) {
278	          followingMap[row.following_id] = true;
279	        }
280	      }
281	    }
282	
283	    const result = articles.map((a: any) => {
284	      const article = a as any;
285	      const tagNames = (article.tagList as Array<{ name: string }> || []).map((t) => t.name);
286	      return {
287	        ...formatArticleResponse(
288	          article,
289	          tagNames,
290	          favoritedMap[article.id] ?? false,
291	          favCountMap[article.id] ?? 0,
292	          currentUserId,
293	        ),
294	        author: {
295	          username: article.author.username,
296	          bio: article.author.bio ?? null,
297	          image: article.author.image ?? null,
298	          following: followingMap[article.author.id] ?? false,
299	        },
300	      };
301	    });
302	
303	    return reply.send({
304	      articles: result,
305	      articlesCount: total,
306	    });
307	  });
308	
309	  // GET /api/articles/:slug - 단일 아티클 조회
310	  app.get("/api/articles/:slug", async (request: any, reply) => {
311	    const slug = request.params.slug as string;
312	    const token = extractToken(request);
313	
314	    const article = await prisma.article.findUnique({
315	      where: { slug },
316	      include: {
317	        author: {
318	          select: { id: true, username: true, bio: true, image: true },
319	        },
320	        tagList: { select: { name: true } },
321	      },
322	    });
323	
324	    if (!article) {
325	      return reply.code(404).send({ errors: { article: ["not found"] } });
326	    }
327	
328	    // 현재 사용자 ID 추출
329	    let currentUserId: string | null = null;
330	    if (token) {
331	      try {
332	        currentUserId = verifyToken(token)?.id ?? null;
333	      } catch {
334	        /* ignore */
335	      }
336	    }
337	
338	    // favorited 상태 및 favoritesCount 조회
339	    const favs = await prisma.favorite.findMany({
340	      where: { articleId: article.id },
341	      select: { userId: true },
