import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import prisma from "../lib/prisma.js";
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";

// Authorization 헤더에서 토큰 추출
function extractToken(request: FastifyRequest): string | null {
  const auth = request.headers.authorization;
  if (!auth) return null;
  const match = auth.match(/^Token\s+(.+)$/i);
  return match ? match[1] : null;
}

// 토큰 디코딩 (예외 처리 포함)
function verifyToken(token: string): { id: string; username: string; email: string } | null {
  try {
    return jwt.verify(token, JWT_SECRET) as any;
  } catch {
    return null;
  }
}

// 슬러그 생성: 소문자, 공백→하이픈, 특수문자 제거, 중복 슬러그 처리
function slugify(title: string, existingSlugs: string[] = []): string {
  let slug = title
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_]+/g, "-")
    .replace(/^-+|-+$/g, "");
  let suffix = 1;
  while (existingSlugs.includes(slug)) {
    slug = `${slug}-${suffix++}`;
  }
  return slug;
}

// 태그 정규화: 소문자, 공백 제거, 빈 값 필터링
function normalizeTags(tagList: (string | null | undefined)[]): string[] {
  if (!tagList) return [];
  const tags = tagList
    .map((t) => {
      if (t === null || t === undefined || t === "") return null;
      return t.trim().toLowerCase();
    })
    .filter((t): t is string => t !== null && t !== "");
  return [...new Set(tags)];
}

// 아티클 응답 포맷팅 헬퍼 (태그, 즐겨찾기, 저자 정보 포함)
function formatArticleResponse(
  article: any,
  tagNames: string[],
  favorited: boolean,
  favoritesCount: number,
  currentUserId: string | null,
): any {
  let following = false;
  if (currentUserId && currentUserId !== article.authorId) {
    following = false;
  }
  return {
    title: article.title,
    slug: article.slug,
    description: article.description,
    body: article.body,
    tagList: tagNames,
    createdAt: article.createdAt,
    updatedAt: article.updatedAt,
    favorited,
    favoritesCount,
    author: {
      username: article.author.username,
      bio: article.author.bio ?? null,
      image: article.author.image ?? null,
      following,
    },
  };
}

export async function articlesRoutes(app: FastifyInstance): Promise<void> {
  // POST /api/articles - 아티클 생성
  app.post("/api/articles", async (request, reply) => {
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const { article } = (request.body as any) as { article?: any };
    const { title, description, body, tagList } = article || {};

    // 필수 필드 검증
    if (!title || title.trim() === "") {
      return reply.code(422).send({ errors: { title: ["can't be blank"] } });
    }
    if (!description || description.trim() === "") {
      return reply.code(422).send({ errors: { description: ["can't be blank"] } });
    }
    if (!body || body.trim() === "") {
      return reply.code(422).send({ errors: { body: ["can't be blank"] } });
    }

    const decoded = verifyToken(token);
    if (!decoded) {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }
    const normalizedTags = normalizeTags(tagList);

    // 태그 조회/생성
    let tagRecords: { id: string; name: string }[] = [];
    if (normalizedTags.length > 0) {
      const existingTags = await prisma.tag.findMany({
        where: { name: { in: normalizedTags } },
        select: { id: true, name: true },
      });
      const existingNames = new Set(existingTags.map((t) => t.name));
      const newTags = normalizedTags.filter((n) => !existingNames.has(n));

      if (newTags.length > 0) {
        await prisma.tag.createMany({
          data: newTags.map((name) => ({ name })),
        });
      }
      tagRecords = await prisma.tag.findMany({
        where: { name: { in: normalizedTags } },
        select: { id: true, name: true },
      });
    }

    // 기존 슬러그 목록 조회 후 중복 처리
    const existingSlugs = await prisma.article.findMany({
      select: { slug: true },
    });
    const existingSlugList = existingSlugs.map((a) => a.slug);
    const slug = slugify(title, existingSlugList);
    const created = await prisma.article.create({
      data: {
        title: title.trim(),
        description: description.trim(),
        body: body.trim(),
        slug,
        authorId: decoded.id,
        ...(tagRecords.length > 0
          ? { tagList: { connect: tagRecords.map((t) => ({ id: t.id })) } }
          : {}),
      },
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tagList: { select: { name: true } },
      },
    });

    // 아티클 생성 후 태그 이름 추출
    const tagNames = (created.tagList as Array<{ name: string }> || []).map(
      (t) => t.name,
    );

    // favorited 상태 기본값
    let favorited = false;
    let favoritesCount = 0;

    return reply.code(201).send({
      article: formatArticleResponse(created, tagNames, favorited, favoritesCount, null),
    });
  });

  // GET /api/articles - 아티클 목록 조회 (필터: author, tag, favorited)
  app.get("/api/articles", async (request: any, reply) => {
    const token = extractToken(request);
    const authorFilter = request.query?.author as string | undefined;
    const tagFilter = request.query?.tag as string | undefined;
    const favoritedFilter = request.query?.favorited as string | undefined;
    const limit = Math.min(parseInt(request.query?.limit as string ?? "20", 10), 100);
    const offset = parseInt(request.query?.offset as string ?? "0", 10);

    // 현재 사용자 ID 추출
    let currentUserId: string | null = null;
    if (token) {
      try {
        currentUserId = verifyToken(token)?.id ?? null;
      } catch {
        /* invalid token */
      }
    }

    // favorited 필터 — 먼저 존재하여 articleIds 확보
    let favArticleIds: string[] = [];
    if (favoritedFilter) {
      const favUser = await prisma.user.findUnique({ where: { username: favoritedFilter } });
      if (!favUser) {
        return reply.send({ articles: [], articlesCount: 0 });
      }
      const favResults = await prisma.favorite.findMany({
        where: { userId: favUser.id },
        select: { articleId: true },
      });
      favArticleIds = favResults.map((f) => f.articleId);
    }

    // author 필터
    let authorId: string | undefined;
    if (authorFilter) {
      const author = await prisma.user.findUnique({ where: { username: authorFilter } });
      if (!author) {
        return reply.send({ articles: [], articlesCount: 0 });
      }
      authorId = author.id;
    }

    // tag 필터
    let tagId: string | undefined;
    if (tagFilter) {
      const tag = await prisma.tag.findUnique({ where: { name: tagFilter } });
      if (!tag) {
        return reply.send({ articles: [], articlesCount: 0 });
      }
      tagId = tag.id;
    }

    // where 조건 구성
    const where: any = {};
    if (authorId) where.authorId = authorId;
    if (favArticleIds.length > 0) {
      where.id = { in: favArticleIds };
    }
    if (tagId) {
      where.tags = { some: { id: tagId } };
    }

    // 전체 카운트
    const total = await prisma.article.count({ where });

    const articles = await prisma.article.findMany({
      where,
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tagList: { select: { name: true } },
      },
      orderBy: { createdAt: "desc" },
      take: limit,
      skip: offset,
    });

    // favorited 상태 batch 체크
    const articleIds = articles.map((a: any) => a.id);
    let favoritedMap: Record<string, boolean> = {};
    let favCountMap: Record<string, number> = {};

    if (articleIds.length > 0) {
      for (const aid of articleIds) {
        const favs = await prisma.favorite.findMany({
          where: { articleId: aid },
          select: { userId: true },
        });
        favCountMap[aid] = favs.length;
        if (favs.some((f) => f.userId === currentUserId)) {
          favoritedMap[aid] = true;
        }
      }
    }

    // 팔로우 관계 batch 조회
    let followingMap: Record<string, boolean> = {};
    if (articles.length > 0 && currentUserId) {
      const followedAuthorIds = articles
        .map((a: any) => a.author.id)
        .filter((id: string) => id);
      if (followedAuthorIds.length > 0) {
        const followResults = await prisma.$queryRaw<{ following_id: string }[]>`
          SELECT following_id FROM "Follow" WHERE follower_id = ${currentUserId} AND following_id IN (${followedAuthorIds})
        `;
        for (const row of followResults) {
          followingMap[row.following_id] = true;
        }
      }
    }

    const result = articles.map((a: any) => {
      const article = a as any;
      const tagNames = (article.tagList as Array<{ name: string }> || []).map((t) => t.name);
      return {
        ...formatArticleResponse(
          article,
          tagNames,
          favoritedMap[article.id] ?? false,
          favCountMap[article.id] ?? 0,
          currentUserId,
        ),
        author: {
          username: article.author.username,
          bio: article.author.bio ?? null,
          image: article.author.image ?? null,
          following: followingMap[article.author.id] ?? false,
        },
      };
    });

    return reply.send({
      articles: result,
      articlesCount: total,
    });
  });

  // GET /api/articles/:slug - 단일 아티클 조회
  app.get("/api/articles/:slug", async (request: any, reply) => {
    const slug = request.params.slug as string;
    const token = extractToken(request);

    const article = await prisma.article.findUnique({
      where: { slug },
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tagList: { select: { name: true } },
      },
    });

    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    // 현재 사용자 ID 추출
    let currentUserId: string | null = null;
    if (token) {
      try {
        currentUserId = verifyToken(token)?.id ?? null;
      } catch {
        /* ignore */
      }
    }

    // favorited 상태 및 favoritesCount 조회
    const favs = await prisma.favorite.findMany({
      where: { articleId: article.id },
      select: { userId: true },
    });
    const favoritesCount = favs.length;
    const favorited = favs.some((r) => r.userId === currentUserId);

    const tagNames = (article.tagList as Array<{ name: string }> || []).map((t) => t.name);

    return reply.send({
      article: formatArticleResponse(article, tagNames, favorited, favoritesCount, currentUserId),
    });
  });

  // PUT /api/articles/:slug - 아티클 수정
  app.put("/api/articles/:slug", async (request: any, reply) => {
    const slug = request.params.slug as string;
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: true, tagList: { select: { name: true } } },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    const decoded = verifyToken(token);
    if (!decoded) {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }
    if (decoded.id !== article.authorId) {
      return reply.code(403).send({ errors: { article: ["not found"] } });
    }

    const { article: updateData } = (request.body as any) as { article?: any };
    const updates: any = {};
    const tagList = updateData?.tagList;

    if (updateData.title !== undefined && updateData.title.trim() !== "") {
      updates.title = updateData.title.trim();
    }
    if (updateData.description !== undefined) updates.description = updateData.description.trim();
    if (updateData.body !== undefined) updates.body = updateData.body.trim();

    // tagList 처리: null이면 422, 배열이면 처리, 없으면 그대로
    if (tagList === null) {
      return reply.code(422).send({ errors: { tagList: ["can't be blank"] } });
    }
    if (tagList !== undefined) {
      const normalizedTags = normalizeTags(tagList);
      if (normalizedTags.length > 0) {
        const existingTags = await prisma.tag.findMany({
          where: { name: { in: normalizedTags } },
          select: { id: true, name: true },
        });
        const existingNames = new Set(existingTags.map((t) => t.name));
        const newTags = normalizedTags.filter((n) => !existingNames.has(n));
        if (newTags.length > 0) {
          await prisma.tag.createMany({
            data: newTags.map((name) => ({ name })),
            skipDuplicates: true,
          });
        }
        const tagRecords = await prisma.tag.findMany({
          where: { name: { in: normalizedTags } },
          select: { id: true, name: true },
        });
        updates.tagList = {
          set: tagRecords.map((t) => ({ id: t.id })),
        };
      } else {
        // 빈 배열이면 모든 태그 해제
        updates.tagList = { set: [] };
      }
    }

    // slug 변경 처리
    const newSlug = updates.title ? slugify(updates.title) : slug;
    updates.slug = newSlug;

    const updated = await prisma.article.update({
      where: { slug },
      data: updates,
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tagList: { select: { name: true } },
      },
    });

    // favorited 상태 확인
    let favorited = false;
    let favoritesCount = 0;
    let currentUserId: string | null = null;
    if (token) {
      try {
        currentUserId = verifyToken(token)?.id ?? null;
      } catch {
        /* ignore */
      }
    }

    const favs = await prisma.favorite.findMany({
      where: { articleId: updated.id },
      select: { userId: true },
    });
    for (const row of favs) {
      favoritesCount++;
      if (row.userId === currentUserId) favorited = true;
    }

    const tagNames = (updated.tagList as Array<{ name: string }> || []).map((t) => t.name);
    return reply.send({
      article: formatArticleResponse(updated, tagNames, favorited, favoritesCount, currentUserId),
    });
  });

  // DELETE /api/articles/:slug - 아티클 삭제
  app.delete("/api/articles/:slug", async (request: any, reply) => {
    const slug = request.params.slug as string;
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    const decoded = verifyToken(token);
    if (!decoded) {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }
    if (decoded.id !== article.authorId) {
      return reply.code(403).send({ errors: { article: ["not found"] } });
    }

    await prisma.article.delete({ where: { slug } });

    return reply.code(204).send();
  });
